import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_INT_RE = re.compile(r'^\d+$')
_CLOCK_RE = re.compile(r'^(\d+):(\d+)(?::(\d+))?$')
_ISO_RE = re.compile(
    r'^P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?$'
)
_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty input")

    original = text
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")

    # Bare integer: seconds
    if _INT_RE.match(stripped):
        return int(stripped)

    # ISO 8601 duration
    if stripped.startswith('P'):
        match = _ISO_RE.match(stripped)
        if not match or all(g is None for g in match.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {original}")
        weeks, days, hours, minutes, seconds = match.groups()
        total = 0.0
        if weeks:
            total += float(weeks) * _UNIT_SECONDS['w']
        if days:
            total += float(days) * _UNIT_SECONDS['d']
        if hours:
            total += float(hours) * _UNIT_SECONDS['h']
        if minutes:
            total += float(minutes) * _UNIT_SECONDS['m']
        if seconds:
            total += float(seconds) * _UNIT_SECONDS['s']
        return round(total)

    # Clock notation: hh:mm:ss or mm:ss
    clock_match = _CLOCK_RE.match(stripped)
    if clock_match:
        a, b, c = clock_match.groups()
        if c is None:
            minutes, seconds = int(a), int(b)
            total = minutes * 60 + seconds
        else:
            hours, minutes, seconds = int(a), int(b), int(c)
            total = hours * 3600 + minutes * 60 + seconds
        return total

    # Generic number+unit components
    matches = list(_COMPONENT_RE.finditer(stripped))
    if not matches:
        raise ValueError(f"cannot parse duration: {original}")

    # Ensure the entire string is covered by matches (aside from whitespace)
    remainder = _COMPONENT_RE.sub('', stripped)
    if remainder.strip():
        raise ValueError(f"cannot parse duration: {original}")

    total = 0.0
    for number_str, unit_str in matches:
        unit_key = unit_str.lower()
        if unit_key not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit_str}")
        total += float(number_str) * _UNIT_SECONDS[unit_key]

    return round(total)

